<div class="form-grid"><label>Nombre completo *<input name="name" required value="{{ old('name',optional($user)->name) }}"></label><label>Correo electrónico *<input type="email" name="email" required value="{{ old('email',optional($user)->email) }}"></label><label>Contraseña {{ $user?'':'*' }}<input type="password" name="password" {{ $user?'':'required' }} placeholder="{{ $user?'Dejar vacío para mantener':'Mínimo 8 caracteres' }}"></label><label>Sucursal *<input name="branch" required value="{{ old('branch',optional($user)->branch ?? 'Almacén principal') }}"></label><label>Perfil *<select name="profile">@foreach(['Administrador','Aprobador','Almacenero','Evaluador','Consulta'] as $profile)<option {{ optional($user)->profile===$profile?'selected':'' }}>{{ $profile }}</option>@endforeach</select></label><fieldset><legend>Permisos de módulos *</legend>@foreach(['products'=>'Productos y Servicios','requirements'=>'Requerimientos','approvals'=>'Aprobaciones','logistics'=>'Logística','daily-reports'=>'Parte Diario Digital','users'=>'Usuarios'] as $key=>$label)<label class="check"><input type="checkbox" name="permissions[]" value="{{ $key }}" {{ in_array($key,optional($user)->permissions??[])?'checked':'' }}> {{ $label }}</label>@endforeach</fieldset><label class="check"><input type="checkbox" name="is_active" value="1" {{ optional($user)->is_active!==false?'checked':'' }}> Usuario activo</label></div>
